#!/usr/bin/env python3
"""Provenance check: the Clight ASTs and the verification report against their sources."""

from __future__ import annotations

import argparse
import hashlib
import os
import platform
import re
import subprocess
import sys
from pathlib import Path, PurePosixPath

ROOT = Path(__file__).resolve().parent.parent
CLIGHT_DIR = ROOT / "verification" / "clight"
MANIFEST = CLIGHT_DIR / "manifest.txt"
MANIFEST_HEAD = (
    "# generated by script/dev.sh verify; do not edit\n"
    "# <AST> <SHA-256> <file>: the AST, its source and the files it includes from include/, src/\n"
)
REPORT = ROOT / "doc" / "verification" / "report.md"
LEAN_DIR = ROOT / "verification" / "lean"

INCLUDE_DIR = ("include", "src")
INPUT = (
    "include/",
    "script/axiom_allow.yaml",
    "script/check_frama_c.sh",
    "script/check_spec.py",
    "script/run_frama_c.sh",
    "script/verify_frama_c.sh",
    "spec/",
    "src/",
    "verification/",
)
OPAM_PACKAGE = (
    "rocq-core",
    "coq-flocq",
    "coq-coquelicot",
    "coq-compcert",
    "coq-vst",
    "frama-c",
    "alt-ergo",
)

INCLUDE_RE = re.compile(r'^[ \t]*#[ \t]*include[ \t]*(?:"([^"]+)"|<([^>]+)>)', re.MULTILINE)
SOURCE_FILE_RE = re.compile(r'^[ \t]*Definition source_file := "([^"]+)"\.$', re.MULTILINE)
MANIFEST_RE = re.compile(r"([^\s/]+\.v) ([0-9a-f]{64}) (\S+)")
TARGET_RE = re.compile(r"[a-z0-9]+(?:_[a-z0-9]+)*")
STAMP_RE = re.compile(r"^\| `([^`]+)` \| `([0-9a-f]{64})` \|$", re.MULTILINE)
ROW_RE = re.compile(
    r"^\| [^|]+ \| ([A-Z][A-Z0-9-]*-[ABC][0-9]+) \| [ABC] \| ([^|]+) \| ([^|]+) \| ([^|]+) \|",
    re.MULTILINE,
)
FRAMA_C_OK_RE = re.compile(r"ok \(([1-9][0-9]*)/\1\)")


def rel(path: Path) -> str:
    return path.relative_to(ROOT).as_posix()


def file_digest(path: Path) -> str:
    return hashlib.sha256(path.read_bytes()).hexdigest()


def include_closure(source: str) -> list[str]:
    """Return the source and every file it includes from the repository, transitively, sorted.

    A name is looked up as `clightgen -Iinclude -Isrc` looks it up: a quoted name next to the
    including file, then in include/, then in src/, and must be found; an angle-bracket name in
    include/, then in src/, and is a system header when it is in neither. An include inside a
    comment or a disabled conditional also counts, which can only add files.
    """
    seen = {source}
    pending = [source]
    while pending:
        current = pending.pop()
        text = (ROOT / current).read_text(encoding="utf-8")
        for quoted, angled in INCLUDE_RE.findall(text):
            name = quoted or angled
            base = [PurePosixPath(current).parent] if quoted else []
            for directory in [*base, *map(PurePosixPath, INCLUDE_DIR)]:
                found = PurePosixPath(os.path.normpath(directory / name)).as_posix()
                inside = not found.startswith(("/", "../")) and found != ".."
                if inside and (ROOT / found).is_file():
                    break
            else:
                if angled:
                    continue
                raise ValueError(f'{current}: cannot find the included file "{name}"')
            if found not in seen:
                seen.add(found)
                pending.append(found)
    return sorted(seen)


def ast_source(ast: Path) -> str:
    match = SOURCE_FILE_RE.search(ast.read_text(encoding="utf-8"))
    if match is None:
        raise ValueError(f"{rel(ast)}: no Info.source_file")
    source = match.group(1)
    if not (ROOT / source).is_file():
        raise ValueError(f"{rel(ast)}: source file {source} does not exist")
    return source


def ast_entry(ast: Path) -> dict[str, str]:
    """Map the AST and every file its source reads to the file's SHA-256."""
    files = [rel(ast), *include_closure(ast_source(ast))]
    return {path: file_digest(ROOT / path) for path in files}


def read_manifest() -> dict[str, dict[str, str]]:
    entry: dict[str, dict[str, str]] = {}
    for number, line in enumerate(MANIFEST.read_text(encoding="utf-8").splitlines(), 1):
        if not line or line.startswith("#"):
            continue
        match = MANIFEST_RE.fullmatch(line)
        if match is None:
            raise ValueError(f"{rel(MANIFEST)}:{number}: malformed line")
        ast, digest, path = match.groups()
        if path in entry.setdefault(ast, {}):
            raise ValueError(f"{rel(MANIFEST)}:{number}: duplicate entry for {ast} {path}")
        entry[ast][path] = digest
    return entry


def write_manifest(target: str) -> int:
    """Record the ASTs of one CompCert target; keep the entries of the existing ASTs of others."""
    if not TARGET_RE.fullmatch(target):
        raise ValueError(f"invalid CompCert target '{target}'")
    suffix = f"_{target}.v"
    old = read_manifest() if MANIFEST.is_file() else {}
    entry = {
        ast: files
        for ast, files in old.items()
        if not ast.endswith(suffix) and (CLIGHT_DIR / ast).is_file()
    }
    asts = sorted(CLIGHT_DIR.glob(f"*{suffix}"))
    for ast in asts:
        source = ast_source(ast)
        if source != f"src/{ast.name.removesuffix(suffix)}.c":
            raise ValueError(f"{rel(ast)}: Info.source_file is {source}, not named after the AST")
        entry[ast.name] = ast_entry(ast)
    lines = [
        f"{ast} {entry[ast][path]} {path}\n" for ast in sorted(entry) for path in sorted(entry[ast])
    ]
    MANIFEST.write_text(MANIFEST_HEAD + "".join(lines), encoding="utf-8")
    return len(asts)


def check_manifest(errors: list[str]) -> int:
    if not MANIFEST.is_file():
        errors.append(f"{rel(MANIFEST)} does not exist")
        return 0
    entry = read_manifest()
    asts = sorted(CLIGHT_DIR.glob("*.v"))
    for ast in asts:
        recorded = entry.pop(ast.name, None)
        if recorded is None:
            errors.append(f"{rel(ast)} is not in {rel(MANIFEST)}")
            continue
        try:
            current = ast_entry(ast)
        except ValueError as exc:
            errors.append(str(exc))
            continue
        for path in sorted(recorded.keys() | current.keys()):
            if path not in current:
                errors.append(f"{ast.name}: {path} is in the manifest but no longer read")
            elif path not in recorded:
                errors.append(f"{ast.name}: {path} is read but not in the manifest")
            elif recorded[path] != current[path]:
                errors.append(f"{ast.name}: {path} changed since the AST was checked")
    for ast in sorted(entry):
        errors.append(f"{rel(MANIFEST)} lists {ast}, which does not exist")
    return len(asts)


def listed_file(top: str) -> list[str]:
    """Files git tracks or would track at or under top (ignored files left out), sorted."""
    try:
        out = subprocess.run(
            ["git", "ls-files", "-z", "--cached", "--others", "--exclude-standard", "--", top],
            cwd=ROOT,
            capture_output=True,
            check=True,
        ).stdout
    except (OSError, subprocess.CalledProcessError) as exc:
        raise ValueError(f"cannot list the files of {top} with git ls-files: {exc}") from exc
    return sorted({path for path in out.decode().split("\0") if path and (ROOT / path).is_file()})


def input_digest() -> dict[str, str]:
    """SHA-256 of the `sha256sum` listing of each input file or directory, in path order."""
    digest = {}
    for top in INPUT:
        listing = "".join(f"{file_digest(ROOT / path)}  {path}\n" for path in listed_file(top))
        digest[top] = hashlib.sha256(listing.encode()).hexdigest()
    return digest


def command_line(cmd: list[str], cwd: Path) -> str:
    try:
        proc = subprocess.run(cmd, cwd=cwd, capture_output=True, text=True)
    except OSError as exc:
        return f"unknown ({cmd[0]}: {exc.strerror})"
    if proc.returncode != 0 or not proc.stdout.strip():
        return f"unknown ({' '.join(cmd)} exited with {proc.returncode})"
    return proc.stdout.strip().splitlines()[0]


def tool_version() -> list[tuple[str, str]]:
    """Platform, Lean and the opam packages of the prover switch, as the gate's run sees them."""
    tool = [
        ("platform", f"{platform.system()} {platform.machine()}"),
        ("lean", command_line(["lake", "env", "lean", "--version"], LEAN_DIR)),
    ]
    cmd = ["opam", "list", "--installed", "--short", "--columns=name,version", *OPAM_PACKAGE]
    try:
        proc = subprocess.run(cmd, cwd=ROOT, capture_output=True, text=True)
    except OSError as exc:
        return tool + [(package, f"unknown (opam: {exc.strerror})") for package in OPAM_PACKAGE]
    if proc.returncode != 0:
        why = f"unknown (opam list exited with {proc.returncode})"
        return tool + [(package, why) for package in OPAM_PACKAGE]
    installed = dict(line.split()[:2] for line in proc.stdout.splitlines() if len(line.split()) > 1)
    return tool + [(package, installed.get(package, "not installed")) for package in OPAM_PACKAGE]


def render_stamp(tool: list[tuple[str, str]]) -> str:
    lines = ["| Input | SHA-256 |", "|---|---|"]
    lines += [f"| `{top}` | `{digest}` |" for top, digest in input_digest().items()]
    lines += ["", "| Tool | Version |", "|---|---|"]
    for name, version in tool:
        escaped = version.replace("|", "\\|")
        lines.append(f"| {name} | {escaped} |")
    return "\n".join(lines)


def check_report(errors: list[str]) -> None:
    text = REPORT.read_text(encoding="utf-8")
    stamp: dict[str, str] = {}
    for top, digest in STAMP_RE.findall(text):
        if top in stamp:
            errors.append(f"{rel(REPORT)}: two stamp rows for {top}")
        stamp[top] = digest
    if sorted(stamp) != sorted(INPUT):
        errors.append(f"{rel(REPORT)}: no stamp with exactly the inputs {', '.join(INPUT)}")
        return
    for top, digest in input_digest().items():
        if stamp[top] != digest:
            errors.append(f"{top} changed since {rel(REPORT)} was generated")
    rows = ROW_RE.findall(text)
    if not rows:
        errors.append(f"{rel(REPORT)}: no theorem row")
    for tid, lean, rocq, frama_c in rows:
        for prover, cell in (("Lean", lean.strip()), ("Rocq", rocq.strip())):
            if cell not in ("ok", "–"):
                errors.append(f"{rel(REPORT)}: {tid} [{prover}] is '{cell}'")
        cell = frama_c.strip()
        if cell != "–" and not FRAMA_C_OK_RE.fullmatch(cell):
            errors.append(f"{rel(REPORT)}: {tid} [Frama-C] is '{cell}'")


def main() -> int:
    ap = argparse.ArgumentParser(description=__doc__.split("\n")[0])
    mode = ap.add_mutually_exclusive_group()
    mode.add_argument(
        "--write-manifest",
        metavar="TARGET",
        help="record the ASTs of a CompCert target (script/dev.sh verify, after the Clight check)",
    )
    mode.add_argument(
        "--digest", action="store_true", help="print the digest of each input of the stamp"
    )
    args = ap.parse_args()

    errors: list[str] = []
    try:
        if args.write_manifest:
            count = write_manifest(args.write_manifest)
            print(f"provenance: {count} AST(s) of {args.write_manifest} in {rel(MANIFEST)}")
            return 0
        if args.digest:
            for top, digest in input_digest().items():
                print(f"{digest}  {top}")
            return 0
        count = check_manifest(errors)
        check_report(errors)
    except (OSError, ValueError) as exc:
        print(f"error: {exc}", file=sys.stderr)
        return 1
    if errors:
        for e in errors:
            print(f"error: {e}", file=sys.stderr)
        print(
            f"rerun script/dev.sh verify and commit {rel(MANIFEST)} and {rel(REPORT)}",
            file=sys.stderr,
        )
        return 1
    print(f"provenance: {count} Clight AST(s) and {rel(REPORT)} match their sources")
    return 0


if __name__ == "__main__":
    sys.exit(main())
